import { groupByCollection } from '@/lib/services/nft.service';
import { MOCK_ETH_USD } from '@/lib/mock/portfolio';
import type { NftCollection, NftItem } from '@/types';

/**
 * Demo NFTs for the gallery.
 *
 * Collections, contract addresses, and OpenSea paths are the real ones, so a
 * card's link lands on the collection it claims to be from. Artwork is local
 * (`/public/mock`, generated by `scripts/generate-mock-art.mjs`) rather than a
 * remote thumbnail: a placeholder host can go away, and a gallery of broken
 * images is a worse demo than a gallery of abstract ones.
 */

/** Fixed acquisition dates, kept as UTC literals so the demo never depends on the clock. */
function acquired(year: number, month: number, day: number): number {
  return Date.UTC(year, month - 1, day);
}

interface MockCollection {
  address: `0x${string}`;
  name: string;
  /** Collection floor in ETH, the unit marketplaces quote it in. */
  floorEth: number;
  /** Local artwork prefix; each token appends its own index. */
  artPrefix: string;
  tokens: readonly {
    tokenId: string;
    name: string;
    description: string;
    acquiredAt: number;
  }[];
}

