/** Local artwork for the token at a given global index, e.g. `/mock/nft-03.svg`. */
function artFor(index: number): string {
  return `/mock/nft-${String(index + 1).padStart(2, '0')}.svg`;
}

/** OpenSea deep link for a token on a chain, matching what the NFT reader builds. */
function openseaUrl(address: string, tokenId: string): string {
  return `https://opensea.io/assets/ethereum/${address}/${tokenId}`;
}

/**
 * The demo gallery: eight tokens across three Ethereum collections.
 *
 * Floors are quoted in ETH and converted at {@link MOCK_ETH_USD}, so the USD
 * figures agree with the token side of the demo portfolio instead of implying a
 * second, different ether price.
 */
export function createMockNfts(): NftItem[] {
  const items: NftItem[] = [];
  let index = 0;

  for (const collection of COLLECTIONS) {
    for (const token of collection.tokens) {
      items.push({
        chainId: 1,
        contractAddress: collection.address,
        tokenId: token.tokenId,
        id: `1:${collection.address.toLowerCase()}:${token.tokenId}`,
        collectionName: collection.name,
        name: token.name,
        description: token.description,
        imageUrl: artFor(index),
        floorPriceNative: collection.floorEth,
        floorPriceUsd: collection.floorEth * MOCK_ETH_USD,
        openseaUrl: openseaUrl(collection.address, token.tokenId),
        spamClassification: 'not_spam',
        acquiredAt: token.acquiredAt
      });
      index += 1;
    }
  }

  return items;
}

/** The demo gallery rolled up per collection, using the reader's own grouping. */
export function createMockNftCollections(): NftCollection[] {
  return groupByCollection(createMockNfts());
}
